import hashlib

class CountMinSketch:
    def __init__(self, width: int = 100, depth: int = 4, seed: int = 0):
        self.width = width
        self.depth = depth
        self.seed = seed
        self.table = [[0] * width for _ in range(depth)]

    def _hash(self, row: int, item: str) -> int:
        digest = hashlib.sha256(f"{self.seed}:{row}:{item}".encode('utf-8')).digest()
        return int.from_bytes(digest[:4], byteorder='big') % self.width

    def add(self, item: str, count: int = 1) -> None:
        for row in range(self.depth):
            col = self._hash(row, item)
            self.table[row][col] += count

    def estimate(self, item: str) -> int:
        return min(self.table[row][self._hash(row, item)] for row in range(self.depth))
